    @Test
    public void testAddWeeksLargeValue() {
        // Start at epoch
        MutableDateTime dt = new MutableDateTime(0, 1, 1, 0, 0, 0, 0);
        // Add 52 weeks (approx 1 year)
        dt.addWeeks(52);

        // Verify that the date has progressed significantly
        assertTrue("Year should have increased or month should have changed", 
            dt.getYear() > 0 || dt.getMonthOfYear() > 1);
    }


}

