public class MutableDateTime_addWeeks_TriageGen2Test {













    @Test
    public void testAddWeeksWithLeapYear() {
        // 2024 is a leap year
        MutableDateTime dt = new MutableDateTime(2024, 2, 25, 0, 0, 0, 0);
        dt.addWeeks(1);

        // Expected: 2024-03-03 (since Feb 29 exists)
        assertEquals(2024, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(3, dt.getDayOfMonth());
    }
}
